import Foundation
import SwiftUI
import Combine

/// Preview-only clip generated by export-experience-motion.mjs from the shared TypeScript geometry.
/// No DiningEntry, TBA, archive or persistence dependency. Same 30 fps samples as the web preview.
struct TasteExperienceMotionClip: Decodable {
    struct Dot: Decodable { let id: String; let group: String; let color: String; let tintColor: String; let role: String }
    struct Label: Decodable { let x: Double; let y: Double; let text: String; let sub: String?; let anchor: String? }
    struct Bridge: Decodable { let points: [Double]; let color: String; let opacity: Double }
    struct Frame: Decodable { let values: [Double]; let summaryOpacity: Double; let bridges: [Bridge]; let labels: [Label]? }
    let schemaVersion: Int
    let fps: Int
    let introFrames: Int
    let loopFrames: Int
    let exampleData: Bool
    let title: String
    let value: String
    let unit: String
    let notes: [String]
    let dots: [Dot]
    let labels: [Label]
    let frames: [Frame]
    let reducedFrame: Frame

    static func load(from url: URL) throws -> Self {
        let clip = try JSONDecoder().decode(Self.self, from: Data(contentsOf: url))
        guard clip.schemaVersion == 4, clip.fps == 30, clip.introFrames >= 0,
              clip.loopFrames > 0, clip.frames.count == clip.introFrames + clip.loopFrames,
              ([clip.reducedFrame] + clip.frames).allSatisfy({ $0.values.count == clip.dots.count * 5 && $0.values.allSatisfy(\.isFinite) && $0.bridges.allSatisfy { $0.points.count == 16 } }) else {
            throw CocoaError(.fileReadCorruptFile)
        }
        return clip
    }

    func frameIndex(at time: Double, reduceMotion: Bool = false) -> Int {
        if reduceMotion { return introFrames }
        let frame = max(0, Int((time * Double(fps) + 0.000001).rounded(.down)))
        return frame < introFrames ? frame : introFrames + (frame - introFrames) % loopFrames
    }
}

/// Pure renderer. The caller supplies time; no wall clock or random state is used here.
struct TasteExperienceClusterMotion: View {
    let clip: TasteExperienceMotionClip
    let time: Double
    var reduceMotion = false
    var selectedGroup: String? = nil

    private func color(_ hex: String, toward: String? = nil, amount: Double = 0) -> Color {
        let value = UInt64(hex.dropFirst(), radix: 16) ?? 0x95867A
        let target = toward.flatMap { UInt64($0.dropFirst(), radix: 16) } ?? value
        func channel(_ shift: Int) -> Double {
            let a = Double((value >> shift) & 255), b = Double((target >> shift) & 255)
            return (a + (b - a) * amount) / 255
        }
        return Color(red: channel(16), green: channel(8), blue: channel(0))
    }
    var body: some View {
        let frame = reduceMotion ? clip.reducedFrame : clip.frames[clip.frameIndex(at: time)]
        Canvas { context, size in
            let side = min(size.width, size.height)
            context.translateBy(x: (size.width - side) / 2, y: (size.height - side) / 2)
            context.scaleBy(x: side / 640, y: side / 640)
            for bridge in frame.bridges {
                let values = bridge.points
                func p(_ i: Int) -> CGPoint { CGPoint(x: values[i * 2], y: values[i * 2 + 1]) }
                var path = Path()
                path.move(to: p(0)); path.addCurve(to: p(3), control1: p(1), control2: p(2))
                path.addLine(to: p(4)); path.addCurve(to: p(7), control1: p(5), control2: p(6)); path.closeSubpath()
                context.fill(path, with: .color(color(bridge.color).opacity(bridge.opacity)))
            }
            for (index, dot) in clip.dots.enumerated() {
                let offset = index * 5
                let x = frame.values[offset], y = frame.values[offset + 1], radius = frame.values[offset + 2]
                let emphasis = selectedGroup == nil || selectedGroup == dot.group ? 1.0 : 0.3
                let path = Path(ellipseIn: CGRect(x: x - radius, y: y - radius, width: radius * 2, height: radius * 2))
                let opacity = frame.values[offset + 3] * emphasis
                let tint = frame.values[offset + 4]
                context.fill(path, with: .color(color(dot.color, toward: dot.tintColor, amount: tint).opacity(opacity)))
            }
            var textContext = context
            textContext.opacity = frame.summaryOpacity
            let ink = Color(red: 48 / 255, green: 46 / 255, blue: 43 / 255)
            textContext.draw(Text(clip.title).font(.custom("Pretendard-Medium", size: 16)).foregroundColor(ink), at: CGPoint(x: 320, y: 279))
            textContext.draw(Text(clip.value).font(.custom("Pretendard-Bold", size: 52)).foregroundColor(ink), at: CGPoint(x: 320, y: 323))
            textContext.draw(Text(clip.unit).font(.custom("Pretendard-Regular", size: 14)).foregroundColor(.secondary), at: CGPoint(x: 320, y: 366))
            for label in frame.labels ?? clip.labels {
                let anchor: UnitPoint = label.anchor == "start" ? .leading : label.anchor == "end" ? .trailing : .center
                textContext.draw(Text(label.text).font(.custom("Pretendard-Medium", size: 12)).foregroundColor(ink), at: CGPoint(x: label.x, y: label.y - 4), anchor: anchor)
                if let sub = label.sub {
                    textContext.draw(Text(sub).font(.custom("Pretendard-Regular", size: 11)).foregroundColor(.secondary), at: CGPoint(x: label.x, y: label.y + 13), anchor: anchor)
                }
            }
        }
        .aspectRatio(1, contentMode: .fit)
        .background(.white)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("예시 데이터. \(clip.title), \(clip.value) \(clip.unit). \(clip.notes.joined(separator: ", "))")
    }
}

/// Standalone native preview controls; does not register or change any app route.
struct TasteExperienceClusterPreview: View {
    let clip: TasteExperienceMotionClip
    @Environment(\.accessibilityReduceMotion) private var systemReduceMotion
    @State private var cursor = 0
    @State private var playing = false
    @State private var reduceMotion = false
    private let timer = Timer.publish(every: 1.0 / 30, on: .main, in: .common).autoconnect()

    var body: some View {
        VStack(spacing: 12) {
            Text("경험 · 예시 데이터").font(.headline)
            TasteExperienceClusterMotion(clip: clip, time: Double(cursor) / Double(clip.fps), reduceMotion: reduceMotion || systemReduceMotion)
            Text(clip.notes.joined(separator: "\n")).font(.caption).foregroundStyle(.secondary)
            HStack {
                Button(playing ? "정지" : "재생") { playing.toggle() }
                Button("처음부터") { cursor = 0 }
                Toggle("모션 줄이기", isOn: $reduceMotion)
            }
            Slider(value: Binding(get: { Double(cursor) }, set: { cursor = Int($0); playing = false }), in: 0...Double(clip.frames.count - 1), step: 1)
            Text("\(cursor) / \(clip.frames.count - 1) 프레임").font(.caption).monospacedDigit()
        }
        .padding()
        .background(.white)
        .onReceive(timer) { _ in
            guard playing, !reduceMotion, !systemReduceMotion else { return }
            cursor += 1
            if cursor >= clip.frames.count { cursor = clip.introFrames }
        }
    }
}
